command:
if (!game.user.isGM) return ui.notifications.warn('Sync World JSON is GM-only.');

const SHIPPED = 'systems/' + game.system.id + '/json/';
const WORLD = 'worlds/' + game.world.id + '/json';
const Picker = foundry.applications.apps.FilePicker.implementation;

/** The world files that replace a shipped file whole, so canon is a copy of the shipped one. */
const FILES = [
  { name: 'affinities.json', what: 'Replaced with the shipped affinities.' },
  { name: 'exp-data.json', what: 'Replaced with the shipped activation XP table.' }
];

/** A file's text past the browser cache, or null when it doesn't exist. */
async function read(path) {
  const response = await fetch(foundry.utils.getRoute(path), { cache: 'no-store' });
  if (response.status === 404) return null;
  if (!response.ok) throw new Error(path + ' responded ' + response.status);
  return response.text();
}

function parsed(text) {
  try { return JSON.parse(text); } catch { return undefined; }
}

/** Whether the world's copy is out of sync: missing, unreadable or different. Only then can it be synced. */
function outOfSync(file, current) {
  if (file.target === null) return false;
  const data = current === null ? undefined : parsed(current);
  return data === undefined || !foundry.utils.equals(data, parsed(file.target));
}

for (const file of FILES) {
  try {
    file.target = await read(SHIPPED + file.name);
    file.syncable = outOfSync(file, await read(WORLD + '/' + file.name));
  } catch (error) {
    file.target = null;
    file.syncable = false;
    console.error('emblem-rpg | Sync World JSON to Canon could not read ' + file.name, error);
  }
}
if (!FILES.some(file => file.syncable)) return ui.notifications.info('Every world JSON file already matches canon.');

const rows = FILES.map(file => '<div class="ed-section">'
  + '<label class="ed-check' + (file.syncable ? '' : ' ed-field--disabled') + '">'
  + '<input type="checkbox" name="' + file.name + '"' + (file.syncable ? '' : ' disabled') + '> ' + file.name + '</label>'
  + '<p class="ed-description">' + file.what + '</p></div>').join('');

const chosen = await foundry.applications.api.DialogV2.wait({
  window: { title: 'Sync World JSON to Canon' },
  classes: ['emblem-rpg', 'dialog-editor'],
  position: { width: 460 },
  content: '<div class="ed-container"><div class="ed-section ed-section--highlight">'
    + '<p class="ed-description" style="font-size:13px; font-style:normal; color:var(--color-light-2);">Overwrites the checked files in ' + WORLD + ' with the system\'s shipped copy.</p>'
    + '</div>' + rows + '</div>',
  buttons: [
    {
      action: 'sync',
      label: 'Sync',
      icon: 'fas fa-rotate',
      default: true,
      callback: (event, button) => [...button.form.querySelectorAll('input[type="checkbox"]:checked')].map(box => box.name)
    },
    { action: 'cancel', label: 'Cancel', callback: () => null }
  ],
  rejectClose: false
});
if (!Array.isArray(chosen)) return;
if (!chosen.length) return ui.notifications.info('No file was checked, so nothing was synced.');

const synced = [];
const failed = [];
try {
  const listing = await Picker.browse('data', 'worlds/' + game.world.id);
  if (!(listing?.dirs ?? []).some(dir => String(dir).split('/').pop() === 'json')) {
    await Picker.createDirectory('data', WORLD, {});
  }
} catch (error) {
  return ui.notifications.error('Could not prepare ' + WORLD + ': ' + error.message);
}
for (const file of FILES.filter(entry => chosen.includes(entry.name))) {
  try {
    const upload = new File([file.target], file.name, { type: 'application/json' });
    const response = await Picker.upload('data', WORLD, upload, {}, { notify: false });
    if (!response?.path) throw new Error('the upload was refused');
    synced.push(file.name);
  } catch (error) {
    failed.push(file.name + ' (' + error.message + ')');
  }
}

console.log('emblem-rpg | Sync World JSON to Canon', { synced, failed });
if (failed.length) ui.notifications.error('Could not sync ' + failed.join(', ') + '.');
if (synced.length) {
  ui.notifications.info('Synced ' + synced.join(', ') + ' to canon. Reload Foundry on every client to apply it.');
}
